import ast
import json
from pathlib import Path
files = [Path("tools/check_benchmark_artifact.py"), Path("tests/test_regressions.py")]
for path in files:
    source = path.read_text(encoding="utf-8")
    ast.parse(source, filename=str(path))
    for number, line in enumerate(source.splitlines(), 1):
        if line.rstrip() != line:
            raise SystemExit(f"{path}:{number}: trailing whitespace")
for name in ("action-log.json", "evaluators/benchmark_run_artifact.schema.json"):
    json.loads(Path(name).read_text(encoding="utf-8"))
print("Python syntax, patch whitespace, and JSON checks passed")
